INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GM4HA1TJH2YK9A8ATG','site_config','01KQJ350GK9DQHMZYC30M6ZM54','{"phone":"(844) 442-4222","address_line1":"201 Believe Lane, Suite B","address_line2":"","city_state":"Georgetown, KY 40324","email":"info@commonwealthaudiology.com","book_url":"#book","hero_heading":"Compassionate hearing care that feels like home.","hero_subtext":"Hearing care you can trust, for every stage of life.","about_tagline":"AUDIOLOGY EXCELLENCE & PATIENT CARE","about_heading":"Commonwealth Audiology","about_text":"Life is full of meaningful sounds: laughter with loved ones, conversations with friends, music you love, and the world sounds all around you. When this changes, it can feel isolating, but we''re here to help. At Commonwealth Audiology, your hearing wellness is our top priority. Every recommendation we make is shaped by what functions for your specific lifestyle needs and the life you love to live. Our Doctor of Audiology, Dr. Tiffany Brown, stays up to date with the latest hearing technology to ensure you receive the most effective and innovative care available.","team_heading":"Meet Your Local Hearing Professionals","team_text":"At Commonwealth Audiology, our focus is on restoring clarity, comfort, and confidence so you can fully participate in the world around you. With superior guidance, clinical excellence, and care centered on you, we partner with our patients and their families each and every day.","hours_mon":"9:00am - 5:00pm","hours_tue":"9:00am - 5:00pm","hours_wed":"9:00am - 5:00pm","hours_thu":"9:00am - 5:00pm","hours_fri":"9:00am - 5:00pm","hours_sat":"9:00am - 1:00pm","hours_sun":"Closed","map_embed_url":"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3134!2d-84.5603!3d38.2098!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMzjCsDEyJzM1LjMiTiA4NMKwMzMnMzcuMSJX!5e0!3m2!1sen!2sus!4v1234567890","services_heading":"Audiology Services in Georgetown, KY","services_subtext":"At Commonwealth Audiology, we provide hearing care to meet your every need. It''s our commitment to make sure you can hear every moment clearly.","hearing_aids_heading":"Hearing Aids & Hearing Aid Services","hearing_aids_subtext":"We provide best-in-class hearing aid solutions with expert fittings, adjustments, repairs, and ongoing maintenance so you can hear your best every day.","protection_heading":"Hearing Protection Solutions in Georgetown, KY","protection_subtext":"For anyone exposed to loud noise, custom ear protection offers the safest and most comfortable way to preserve your hearing.","testimonials_heading":"What Our Patients Are Saying","faq_heading":"Frequently Asked Questions","news_heading":"News & Articles","footer_tagline":"Compassionate hearing care in Georgetown, KY. Helping you hear every meaningful moment of life."}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GQ3WPEY0TR76AVKQPD','services','01KQJ350GPSVZ2Y02YX71CDAMJ','{"title":"Hearing Evaluations","description":"A comprehensive hearing evaluation is the first step toward better hearing. Our Doctor of Audiology will assess your hearing health using the latest diagnostic tools and techniques.","link_url":"/services","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GRSMA0MV8VEQYF5WQM','services','01KQJ350GR4MVYAX0Y2RQ0HJE3','{"title":"Hearing Loss Evaluation & Treatment","description":"We work together to understand what you are experiencing and recommend treatment options tailored to your specific type and degree of hearing loss with confidence.","link_url":"/services","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GT87J4PTFED13MZRHF','services','01KQJ350GS985T25ZZ6TJ8G6Q7','{"title":"Ear Wax Removal","description":"Excess earwax can sometimes accumulate and cause hearing loss. Our safe, professional ear wax removal services restore your hearing clarity quickly and comfortably.","link_url":"/services","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GVAA7K3F45DG6D3QEA','services','01KQJ350GV7VZ9S4ZW94JDGBK1','{"title":"Tinnitus Evaluations & Treatment","description":"Ringing, buzzing, or whooshing in the ears can be stressful. We fully evaluate your tinnitus and discuss various treatment options designed to find what works best for you.","link_url":"/services","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
