INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HAW7BHNKMVY6A2VBSB','testimonials','01KQJ350HAHBR7HKBPGNEW79M2','{"patient_name":"Laci Wills","rating":"5","review":"Absolutely love this place! The staff is so friendly and helpful. My hearing aids have changed my life and I couldn''t be more grateful!","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HC6WRYF0J03Z36D1ZB','testimonials','01KQJ350HBFBJNC7NBZNZ4Q3YF','{"patient_name":"Tracy Davis","rating":"5","review":"Professional, knowledgeable, and kind. The whole team made me feel comfortable from the moment I walked in. Highly recommend Commonwealth Audiology!","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HD4F01GQTJZFQNPQHJ','testimonials','01KQJ350HD10YKTSJZ8A45ZC47','{"patient_name":"Ola Mack","rating":"5","review":"Great experience from start to finish. Dr. Brown took the time to really listen and find the perfect solution for me. Outstanding care!","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HEB2XV79ANQJT9NT9A','testimonials','01KQJ350HEV9BXAWTYYZY5ZR4W','{"patient_name":"Garrett Hanover","rating":"5","review":"I was nervous about getting hearing aids, but the team here made the whole process easy and stress-free. Amazing patient care!","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HF2D69NQ2MJF7V0CB9','testimonials','01KQJ350HFJZ9T3RQ8V5XKPBPZ','{"patient_name":"Audra Rugg","rating":"5","review":"Commonwealth Audiology exceeded all my expectations. The care is professional, the staff are wonderful, and I can finally hear again!","sort_order":"5"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HH5MP01DAHDHVPMBX0','faq','01KQJ350HGFVSCGTZFGHJ3ZD0K','{"question":"How do I know if I need a hearing aid?","answer":"If you frequently ask people to repeat themselves, have difficulty hearing in noisy environments, or find yourself turning up the TV volume, it may be time for a hearing evaluation. Schedule an appointment with our audiologist for a comprehensive assessment.","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350SJ0RYC6J10BVY1N9F8','faq','01KQJ350SGN0CFQT32TY919VB0','{"question":"Are hearing aids covered by insurance?","answer":"Coverage varies by insurance plan. Many plans offer partial coverage for hearing aids. Our team can help you understand your benefits and explore financing options to make hearing care accessible for you.","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VBGH6BJV5W9AHPGRJP','faq','01KQJ350V7TTJK0FDBNMKDC3X9','{"question":"How often should I get a hearing test?","answer":"Adults should have their hearing tested every 3-5 years, or more frequently if you notice changes. Those with existing hearing loss or high noise exposure should be tested annually.","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VG8BTC6AY0XFQKSWFV','faq','01KQJ350VE5HBKRJVX0X3M5CRD','{"question":"Can I get a hearing aid without a fitting?","answer":"A professional fitting is essential for optimal hearing aid performance. Proper fitting ensures the device is programmed correctly for your specific hearing loss, fits comfortably, and delivers the best possible sound quality.","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VRJH9CR0ENPSWZYBBH','faq','01KQJ350VMXP8HWAXRKNVGP06N','{"question":"How can hearing aids help with tinnitus?","answer":"Many modern hearing aids include tinnitus masking features that produce soothing sounds to reduce the perception of ringing. Combined with hearing amplification, they can significantly improve quality of life for tinnitus sufferers.","sort_order":"5"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VZGN38642W6JGH6YQ7','hearing_protection','01KQJ350VYRQDZC2JENHFDX4ZK','{"title":"Custom Hearing Protection & Ear Molds","description":"Our custom ear solutions reduce harmful sounds while keeping important sounds audible, so you can work safely and enjoy what you love without fear of hearing damage.","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350W520JCVTA914XCKRQ7','hearing_protection','01KQJ350W3D6DX86YYR7VEQ4K7','{"title":"Hearing Protection for Musicians","description":"Musicians are at high risk for regular exposure to loud volumes that can harm their hearing. We provide specially designed protection that lets you enjoy music you love while preserving your hearing for years to come.","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350WPRVN4XB8Q4PEJ10B5','hearing_protection','01KQJ350WF2QWY106GWWZMGA4S','{"title":"Hearing Protection for Hunters","description":"Sudden, loud blasts from firearms can cause severe, permanent hearing damage. Our custom hunter''s ear protection provides incredible ambient sound awareness while protecting your hearing from dangerous impulse noise.","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
